package java.util;
public final class Locale implements java.io.Serializable, Cloneable { private final String language,country; public static final Locale ROOT=new Locale("",""), ENGLISH=new Locale("en"), US=new Locale("en","US"), UK=new Locale("en","GB"), KOREAN=new Locale("ko"), KOREA=new Locale("ko","KR"), JAPAN=new Locale("ja","JP"), CHINA=new Locale("zh","CN"), GERMANY=new Locale("de","DE"), FRANCE=new Locale("fr","FR"); private static Locale current=US; public Locale(String l){this(l,"");} public Locale(String l,String c){if(l==null||c==null)throw new NullPointerException();language=l.toLowerCase();country=c.toUpperCase();} public static Locale getDefault(){return current;} public static void setDefault(Locale l){if(l==null)throw new NullPointerException();current=l;} public String getLanguage(){return language;} public String getCountry(){return country;} public String toString(){return country.length()==0?language:language+"_"+country;} public boolean equals(Object x){return x instanceof Locale && language.equals(((Locale)x).language)&&country.equals(((Locale)x).country);} public int hashCode(){return language.hashCode()*31+country.hashCode();} }
